actions.script:
const out = ec.service.sync().name('mantle.marketing.MarketingWorkspaceServices.get#CalendarItems').parameters({start: start || '',
    end: end || ''}).call() || {}
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
// follow-up 9: a send's link only for who may open SendDetail (placesFor: the user's capabilities read once)
const place = ec.resource.script('component://mr-boss/service/ironstone/marketing/Marketing.js').placesFor(appRoot)
const editable = {}
const canEdit = (workEffortId) => {
    if (!Object.hasOwn(editable, workEffortId)) {
        const access = ec.service.sync().name('ironstone.commons.CalendarServices.get#EventAccessInfo').parameters({workEffortId: workEffortId,
            need: 'check'}).call() || {}
        ec.message.clearErrors()
        editable[workEffortId] = !!access.canEdit
    }
    return editable[workEffortId]
}
const eventList = Array.from(out.items || []).map((item) => {
    const isEvent = item.kind === 'event'
    return {kind: item.kind, key: item.key, title: item.title + (!isEvent && item.stateText ? ' · ' + item.stateText : ''),
        start: item.startText, end: item.endText, allDay: !!item.allDay, statusId: null, done: false,
        workEffortId: isEvent ? item.workEffortId : null, recurring: isEvent && !!item.recurring,
        recurringEventId: isEvent ? item.seriesWorkEffortId : null, instanceStart: isEvent ? item.instanceStart : null,
        location: item.location || null, color: null, freeBusyOnly: false,
        canEdit: isEvent ? canEdit(item.workEffortId) : false,
        url: place(item.route, item.recordParameter, item.recordId)}
})
ec.web.sendJsonResponse({eventList: eventList, failedSources: out.failedSources || [], skippedCalendarIdList: []})

const out = ec.service.sync().name('ironstone.commons.CalendarServices.get#EventSummary').parameters({workEffortId: workEffortId || '',
    instanceStart: instanceStart || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() || !out.visible ? {visible: false} : {visible: true, event: out.event})

const id = workEffortId || ''
ec.service.sync().name('mantle.marketing.MarketingWorkspaceServices.check#CalendarEvent').parameters({workEffortId: id}).call()
if (!ec.message.hasError()) ec.service.sync().name('ironstone.commons.CalendarServices.get#EventAccessInfo').parameters({workEffortId: id,
    need: 'edit'}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const theScope = scope || 'all'
const out = ec.service.sync().name('mantle.work.EventServices.update#EventOccurrence').parameters({workEffortId: id,
    instanceStart: instanceStart || null, scope: theScope, start: start || null, end: end || null, allDay: allDay || null,
    notify: notify || 'N', eventUrl: '/qapps/Commons/Calendar/EventDetail?workEffortId=' + encodeURIComponent(id),
    allowConflicts: allowConflicts === 'Y' || allowConflicts === 'true'}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({bookingClash: / is booked then: /.test(ec.message.getErrorsString())}); return }
ec.web.sendJsonResponse({targetWorkEffortId: out.targetWorkEffortId, messageInfos: [{type: 'success', message: out.message}]})

const id = workEffortId || ''
ec.service.sync().name('mantle.marketing.MarketingWorkspaceServices.check#CalendarEvent').parameters({workEffortId: id}).call()
if (!ec.message.hasError()) ec.service.sync().name('ironstone.commons.CalendarServices.get#EventAccessInfo').parameters({workEffortId: id,
    need: 'edit'}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const out = ec.service.sync().name('mantle.work.EventServices.cancel#EventOccurrence').parameters({workEffortId: id,
    instanceStart: instanceStart || null, scope: scope || 'all', notify: notify || 'N',
    eventUrl: '/qapps/Commons/Calendar/EventDetail?workEffortId=' + encodeURIComponent(id)}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.commons.CalendarServices.respond#Invitation').parameters({workEffortId: workEffortId || '',
    response: response || '', message: message || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId, messageInfos: [{type: 'success', message: out.resultMessage}]})
